package vn.aicrm.sales;
import vn.aicrm.shared.*;

import java.util.*;
import java.math.*;
import java.time.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import static vn.aicrm.shared.RetailAccess.*;

@Service
public class RetailOperations implements SalesOperationsPort {
  private final RetailAccess r;private final PartnersPort partners;private final RetailDocuments documents;private final FinancePort finance;
  public RetailOperations(RetailAccess r,RetailDocuments documents,FinancePort finance,PartnersPort partners){this.r=r;this.partners=partners;this.documents=documents;this.finance=finance;}
  public Object deliveries(Authentication a){r.require(a,"READ");if(!r.granular(a,"delivery","VIEW"))return List.of();return r.db.queryForList("select v.*,d.number,p.name partner from retail.delivery v join retail.document d on d.tenant_id=v.tenant_id and d.id=v.issue_id left join retail.partner p on p.tenant_id=d.tenant_id and p.id=d.partner_id where v.tenant_id=? and "+r.branchScope(a,"v")+" order by d.created_at desc limit 1000",r.tenant(a));}
  public Object createDelivery(Authentication a,JsonNode x){r.require(a,"SELL");var d=documents.document(a,uuid(x,"issueId"));if(!Set.of("POS","ISSUE").contains(d.get("type"))||!"POSTED".equals(d.get("status")))throw problem("ISSUE_REQUIRED","Giao hàng cần phiếu xuất bán đã ghi");var cod=money(num(x,"cod",BigDecimal.ZERO));var fee=money(num(x,"fee",BigDecimal.ZERO));var debt=r.db.queryForObject("select coalesce(sum(amount-credit-allocated),0) from retail.open_item where tenant_id=? and document_id=?",BigDecimal.class,r.tenant(a),d.get("id"));if(cod.signum()<0||fee.signum()<0||cod.compareTo(debt)>0||fee.compareTo(cod)>0&&cod.signum()>0)throw problem("INVALID_COD","COD không vượt nợ còn mở, phí không âm");UUID id=UUID.randomUUID();r.db.update("insert into retail.delivery(id,tenant_id,branch_id,issue_id,carrier,tracking,cod,fee,note) values(?,?,?,?,?,?,?,?,?)",id,r.tenant(a),d.get("branch_id"),d.get("id"),text(x,"carrier",""),text(x,"tracking",""),cod,fee,text(x,"note",""));return Map.of("id",id);}
  public Object delivery(Authentication a,UUID id,String action,JsonNode x){var t=r.tenant(a);var v=r.one("delivery",t,id);r.branch(a,(UUID)v.get("branch_id"));if(!x.has("version")||x.path("version").asInt(-1)!=((Number)v.get("version")).intValue())throw problem("VERSION_CONFLICT","Đợt giao đã thay đổi",org.springframework.http.HttpStatus.CONFLICT);
    if(action.equals("status")){r.require(a,"SELL");String target=required(x,"status",20),current=v.get("status").toString();var allowed=switch(current){case "PREPARING"->Set.of("SHIPPING","FAILED");case "SHIPPING"->Set.of("PARTIAL","DELIVERED","FAILED");case "PARTIAL"->Set.of("SHIPPING","DELIVERED","FAILED");default->Set.<String>of();};if(!allowed.contains(target))throw problem("INVALID_DELIVERY_STATE","Không thể chuyển trạng thái giao hàng");r.db.update("update retail.delivery set status=?,note=?,version=version+1 where tenant_id=? and id=?",target,text(x,"note",""),t,id);}
    else if(action.equals("settle")){r.require(a,"FINANCE");if(!Set.of("DELIVERED","PARTIAL").contains(v.get("status")))throw problem("COD_NOT_DELIVERED","Chỉ đối soát COD đã giao");BigDecimal gross=money(num(x,"amount",BigDecimal.ZERO)),fee=money(num(x,"fee",BigDecimal.ZERO));if(gross.signum()<=0||fee.signum()<0||fee.compareTo(gross)>0||gross.compareTo(decimal(v.get("cod")).subtract(decimal(v.get("settled"))))>0)throw problem("COD_EXCEEDED","Đối soát vượt COD còn lại hoặc phí không hợp lệ");var doc=documents.document(a,(UUID)v.get("issue_id"));UUID payment=finance.payment(a,(UUID)v.get("branch_id"),(UUID)doc.get("partner_id"),(UUID)doc.get("id"),"RECEIPT",gross,text(x,"method","BANK"),"COD "+v.get("tracking")+"; thực nhận "+gross.subtract(fee));var items=r.db.queryForList("select * from retail.open_item where tenant_id=? and document_id=? and kind='AR'",t,doc.get("id"));var o=items.getFirst();if(gross.compareTo(decimal(o.get("amount")).subtract(decimal(o.get("credit"))).subtract(decimal(o.get("allocated"))))>0)throw problem("COD_DEBT_CHANGED","Công nợ đã được thu/điều chỉnh; cần đối chiếu COD");finance.allocate(a,payment,(UUID)o.get("id"),gross);if(fee.signum()>0)finance.payment(a,(UUID)v.get("branch_id"),null,(UUID)doc.get("id"),"PAYMENT",fee,"OFFSET","Phí COD "+v.get("tracking"));r.db.update("update retail.delivery set settled=settled+?,actual_fee=actual_fee+?,version=version+1 where tenant_id=? and id=?",gross,fee,t,id);}
    else throw problem("INVALID_ACTION","Thao tác giao hàng không hợp lệ");return r.one("delivery",t,id);
  }



  public Object warrantyList(Authentication a){r.require(a,"READ");if(!r.granular(a,"warranty","VIEW"))return List.of();return r.db.queryForList("select w.*,d.number,s.name product from retail.warranty w join retail.line l on l.tenant_id=w.tenant_id and l.id=w.source_line_id join retail.document d on d.tenant_id=l.tenant_id and d.id=l.document_id join retail.sku s on s.tenant_id=l.tenant_id and s.id=l.sku_id where w.tenant_id=? and "+r.branchScope(a,"w")+" order by w.created_at desc limit 500",r.tenant(a));}
  public Object warranty(Authentication a,JsonNode x){r.require(a,"SELL");var t=r.tenant(a);var l=r.one("line",t,uuid(x,"sourceLineId"));var d=r.one("document",t,(UUID)l.get("document_id"));if(!Set.of("POS","ISSUE").contains(d.get("type"))||!"POSTED".equals(d.get("status")))throw problem("INVALID_WARRANTY_SOURCE","Bảo hành cần giao dịch bán gốc");var snap=r.node(l.get("sku_snapshot"));var days=snap.path("warranty_days").asInt();var sold=((java.sql.Timestamp)d.get("posted_at")).toInstant().atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate();if(days<=0||today().isAfter(sold.plusDays(days)))throw problem("WARRANTY_EXPIRED","Sản phẩm hết hạn hoặc không áp dụng bảo hành");String sn=text(x,"serial","");if("SERIAL".equals(snap.path("tracking").asText())){boolean found=false;for(var serial:r.node(l.get("serials")))found|=sn.equals(serial.asText());if(!found)throw problem("WRONG_SOLD_SERIAL","Serial không đúng giao dịch gốc");if(r.db.queryForObject("select count(*) from retail.warranty where tenant_id=? and serial=? and status<>'HANDED_OVER'",Integer.class,t,sn)>0)throw problem("WARRANTY_DUPLICATE","Serial đang có phiếu bảo hành mở");}
    var wh=r.warehouse(a,uuid(x,"warehouseId"));var qty=positive(x,"qty");if(qty.compareTo(decimal(l.get("base_qty")))>0)throw problem("WARRANTY_QUANTITY","Lượng bảo hành vượt lượng bán");var id=UUID.randomUUID();r.db.update("insert into retail.warranty(id,tenant_id,branch_id,source_line_id,serial,qty,note,warehouse_id) values(?,?,?,?,?,?,?,?)",id,t,wh.get("branch_id"),l.get("id"),sn,qty,required(x,"note",4000),wh.get("id"));return Map.of("id",id);
  }
  public Object warrantyStatus(Authentication a,UUID id,JsonNode x){r.require(a,"SELL");var row=r.one("warranty",r.tenant(a),id);r.branch(a,(UUID)row.get("branch_id"));if(x.path("version").asInt(-1)!=((Number)row.get("version")).intValue())throw problem("VERSION_CONFLICT","Phiếu bảo hành đã thay đổi");String next=required(x,"status",20);var allowed=switch(row.get("status").toString()){case "RECEIVED"->Set.of("PROCESSING");case "PROCESSING"->Set.of("READY");case "READY"->Set.of("HANDED_OVER");default->Set.<String>of();};if(!allowed.contains(next))throw problem("INVALID_STATE","Trạng thái bảo hành không hợp lệ");r.db.update("update retail.warranty set status=?,note=note || ?,version=version+1 where tenant_id=? and id=?",next,"\n"+required(x,"note",4000),r.tenant(a),id);return Map.of("id",id);}
  public Object lookupOriginal(Authentication a,String number){if(!r.granular(a,"returns","LOOKUP_ORIGINAL")&&!r.granular(a,"warranty","LOOKUP_ORIGINAL"))throw problem("PERMISSION_DENIED","Không có quyền tra giao dịch gốc",org.springframework.http.HttpStatus.FORBIDDEN);if(number==null||number.length()<5)throw problem("EXACT_REFERENCE_REQUIRED","Nhập đúng số phiếu bán gốc");var rows=r.db.queryForList("select d.id,d.number,d.partner_id,d.branch_id,d.warehouse_id,d.posted_at,p.name partner from retail.document d left join retail.partner p on p.tenant_id=d.tenant_id and p.id=d.partner_id where d.tenant_id=? and d.number=? and d.type in ('POS','ISSUE') and d.status='POSTED'",r.tenant(a),number);if(rows.isEmpty())throw problem("NOT_FOUND","Không tìm thấy phiếu bán gốc",org.springframework.http.HttpStatus.NOT_FOUND);var result=rows.getFirst();var ls=documents.lines(a,(UUID)result.get("id")).stream().map(l->{var m=new LinkedHashMap<String,Object>();for(var k:List.of("id","sku_id","sku_snapshot","qty","base_qty","unit","ratio","price","discount","net","tax","total","lot","expiry","serials"))m.put(k,l.get(k));return r.clean(m);}).toList();result.put("lines",ls);return result;}



}

